// The commonest paint attribute runs, written as one character each in the files.
const paintTokens: Readonly<Record<string, string>> = {
	"~": ' fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="1.5"',
	"^": ' fill="none" stroke="currentColor" stroke-linejoin="round" stroke-width="1.5"',
	"`": ' fill="none" stroke="currentColor" stroke-linecap="square" stroke-width="1.5"',
	"|": ' fill="none" stroke="currentColor" stroke-width="1.5"',
	"!": ' fill="none" stroke="currentColor" stroke-linecap="round" stroke-width="1.5"',
	"*": ' fill="none" stroke="currentColor" stroke-linecap="square" stroke-linejoin="round" stroke-width="1.5"',
	"@": ' fill="currentColor"',
	$: ' fill="none" stroke="currentColor" stroke-linejoin="bevel" stroke-width="1.5"',
};

/** A stored icon's SVG markup, with its paint attributes written out. */
export const expandIcon = (markup: string): string =>
	markup.replace(/[~^`|!*@$]/g, (token) => paintTokens[token] ?? "");
